import os
import ast

def analyze_file(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    if "legacy_auth" not in content:
        return None

    try:
        tree = ast.parse(content)
    except SyntaxError as e:
        print(f"Syntax error in {filepath}: {e}")
        return None

    results = []

    # We want to find each function definition
    for node in ast.walk(tree):
        if isinstance(node, ast.FunctionDef):
            # Get the exact source lines of this function
            lines = content.splitlines()
            start_line = node.lineno
            # To get end line, we find the maximum lineno of any child node
            end_line = start_line
            for child in ast.walk(node):
                if hasattr(child, 'lineno'):
                    end_line = max(end_line, child.lineno)

            # Extract function body
            func_lines = lines[start_line - 1:end_line]
            func_text = "\n".join(func_lines)

            # Check if legacy_auth is called in this function
            has_legacy_call = False
            for child in ast.walk(node):
                if isinstance(child, ast.Call) and isinstance(child.func, ast.Name) and child.func.id == "legacy_auth":
                    has_legacy_call = True
                    break

            if has_legacy_call:
                # Look for nearby keywords in the same function
                keywords = ["create_", "update_", "delete_", "save_", "write_", "POST", "PUT", "PATCH"]
                matching_keywords = [kw for kw in keywords if kw in func_text]

                # We should also check the function name or file name, but the rule says:
                # "If the surrounding code clearly does a write/mutation (look for nearby
                # create_, update_, delete_, save_, write_, or POST/PUT/PATCH HTTP verbs in the same function)"
                # Let's collect this information
                results.append({
                    "function_name": node.name,
                    "start_line": start_line,
                    "end_line": end_line,
                    "matching_keywords": matching_keywords,
                    "func_text": func_text
                })
    return results

def main():
    for root, dirs, files in os.walk("."):
        if "node_modules" in dirs:
            dirs.remove("node_modules")
        if ".git" in dirs:
            dirs.remove(".git")
        for file in files:
            if file.endswith(".py") and file != "analyze.py" and not filepath_is_auth(os.path.join(root, file)):
                filepath = os.path.join(root, file)
                res = analyze_file(filepath)
                if res:
                    print(f"\n========================================\nFILE: {filepath}")
                    for r in res:
                        print(f"  Function: {r['function_name']} (Lines {r['start_line']}-{r['end_line']})")
                        print(f"  Keywords found: {r['matching_keywords']}")
                        print(f"  Action suggested: {'write' if r['matching_keywords'] else 'read'}")

def filepath_is_auth(path):
    return os.path.basename(path) == "auth.py"

if __name__ == "__main__":
    main()

